CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_id_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS login_attempts (email text NOT NULL, attempted_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS login_attempts_email_time_idx ON login_attempts(email, attempted_at);
CREATE TABLE IF NOT EXISTS films (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL, premise text NOT NULL, genre text NOT NULL, duration_minutes integer NOT NULL CHECK (duration_minutes BETWEEN 1 AND 120), language text NOT NULL DEFAULT 'en', visual_style text NOT NULL DEFAULT '', mode text NOT NULL DEFAULT 'automatic', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')), engine_film_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS films_owner_idx ON films(owner_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS film_contributors (film_id uuid NOT NULL REFERENCES films(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('editor','viewer')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(film_id,user_id));
CREATE TABLE IF NOT EXISTS scenes (id uuid PRIMARY KEY, film_id uuid NOT NULL REFERENCES films(id) ON DELETE CASCADE, position integer NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', UNIQUE(film_id,position));
CREATE TABLE IF NOT EXISTS characters (id uuid PRIMARY KEY, film_id uuid NOT NULL REFERENCES films(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', asset_id text, UNIQUE(film_id,asset_id));
CREATE TABLE IF NOT EXISTS comments (id uuid PRIMARY KEY, film_id uuid NOT NULL REFERENCES films(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, body text NOT NULL CHECK (length(body) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS film_likes (film_id uuid NOT NULL REFERENCES films(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(film_id,user_id));
CREATE TABLE IF NOT EXISTS follows (follower_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, followed_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_id,followed_id), CHECK (follower_id <> followed_id));
